// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2017, "8-9", [{"author":"П. Аркадьев","question":"Какое слово не обозначает спортивную игру?","choices":["<em>баскетбол</em>","<em>волейбол</em>","<em>гандбол</em>","<em>дискобол</em>","<em>бейсбол</em>."],"key":"Г","review":["Названия спортивных игр","Вспомни, в каких из перечисленных видов спорта играют с мячом, а в каком слове слышится «диск».","«Дискобол» — спортсмен, который метает диск. Баскетбол, волейбол, гандбол и бейсбол — названия игр."]},{"author":"Л. Фёдорова","question":"<em>__, негодник!; __, какой умный!; __, прозевал!; __, здорово!; __, пойди сюда!</em>\nКак лучше заполнить пропуски?","choices":["<em>Эх ты</em>; <em>Ух ты</em>; <em>Эй ты</em>; <em>Ишь ты</em>; <em>Ах ты</em>","<em>Ух ты</em>; <em>Ишь ты</em>; <em>Ах ты</em>; <em>Эх ты</em>; <em>Эй ты</em>","<em>Ишь ты</em>; <em>Ах ты</em>; <em>Эх ты</em>; <em>Эй ты</em>; <em>Ух ты</em>","<em>Эй ты</em>; <em>Эх ты</em>; <em>Ишь ты</em>; <em>Ах ты</em>; <em>Ух ты</em>","<em>Ах ты</em>; <em>Ишь ты</em>; <em>Эх ты</em>; <em>Ух ты</em>; <em>Эй ты</em>."],"key":"Д","review":["Междометия и интонация","Начни с последней реплики: «пойди сюда» обращено к тому, чьё внимание надо привлечь. Для досады после промаха тоже есть знакомое междометие.","Получается «Ах ты, негодник!», «Ишь ты, какой умный!», «Эх ты, прозевал!», «Ух ты, здорово!», «Эй ты, пойди сюда!»."]},{"author":"А. Сомин","question":"В каком из этих примеров перед словом <em>батьку</em> должна стоять запятая?","choices":["<em>Костя не ответил, лишь опечаленным взглядом окинул болотные дали, будто надеясь увидеть там (,) батьку</em>. (В. Быков)","<em>Ты ещё плохо знаешь своего (,) батьку. Ты ещё ничего, сынок, о нём не знаешь</em>. (В. Дудинцев)","<em>Вспоминая (,) батьку и его белого коня, старик прослезился</em>. (Д. Карапетян)","<em>Погубил ты (,) батьку, родную дочку свою! Погубила ведьма грешную душу твою!</em> (Н. Гоголь)","<em>На базаре только (,) батьку с маткой не купишь, а так</em> — <em>что твоей душе угодно</em>. (В. Осеева)"],"key":"Г","review":["Запятая перед «батьку»","Определи, где «батьку» — объект действия, а где герой напрямую обращается к человеку.","У Гоголя «батьку» — обращение: «Погубил ты, батьку, родную дочку свою!». В других цитатах слово служит дополнением, например «увидеть кого?»."]},{"author":"П. Аркадьев","question":"В каком из приведённых слов нет приставки?","choices":["<em>разбор</em>","<em>разрешение</em>","<em>разность</em>","<em>раструб</em>","<em>расход</em>."],"key":"В","review":["Границы приставки","У четырёх слов можно найти однокоренные с похожим смыслом без начального «раз-» или «рас-».","«Разбор» связан с «брать», «разрешение» — с «решить», «раструб» — с «труба», «расход» — с «ход». В «разности» сочетание «раз» входит в корень «разн-»."]},{"author":"Е. Муравенко","question":"В книжке-головоломке Антона Тилипмана «Зубака» во многих словах перепутались буквы. Например, была <em>азбука</em> — стала <em>зубака</em>. Постарайтесь правильно расставить буквы в данных ниже «словах», чтобы ответить, какое из них не означает людей.","choices":["<em>чуятели</em>","<em>вотписатели</em>","<em>зловресы</em>","<em>дикокролы</em>","<em>детироли.</em>"],"key":"Г","review":["Буквы из «Зубаки»","Переставляй буквы, сохраняя каждую ровно столько раз, сколько она дана. Четыре слова называют группы людей.","Получаются «учителя», «воспитатели», «взрослые», «крокодилы» и «родители». Людей не называют только «крокодилы»."]},{"author":"Б. Иомдин","question":"В какой паре слова не связаны по смыслу?","choices":["<em>писать — писец</em>","<em>читать — чтец</em>","<em>шить — швец</em>","<em>играть — игрец</em>","<em>спать — спец</em>."],"key":"Д","review":["Действие и деятель","Спроси, описывает ли второе слово человека, который выполняет действие первого.","Писец пишет, чтец читает, швец шьёт, игрец играет. «Спец» — сокращённое «специалист» и со сном не связан."]},{"author":"Е. Бикмаев","question":"В каком предложении на месте пропуска не нужна запятая?","choices":["<em>По воспоминаниям Скотта_ трудно установить хронологию его чтений. Он и сам признавался, что путает даты.</em> (Б. Реизов)","<em>По воспоминаниям Зализняка_ именно после этой поездки он заинтересовался языками, начал учить английский, итальянский и испанский.</em> (А. Лотарёва)","<em>По воспоминаниям бывших абитуриентов_ экзамены проходили иногда весьма непредсказуемо, заставая врасплох своей курьёзностью и неординарностью.</em> (А. Галигузов)","<em>По воспоминаниям Герцена_ Чаадаев обычно был «холоден, серьёзен, умён и зол».</em> (В. Каганов)","<em>По воспоминаниям современников_ комнаты <…> украшала портретная галерея членов семьи Мусиных-Пушкиных…</em> (А. Колосова)"],"key":"А","review":["«По воспоминаниям»","Спроси, означает ли оборот «как сообщается в воспоминаниях» или входит в высказывание как ответ на вопрос «по каким данным?».","«Установить хронологию по воспоминаниям Скотта» — установить её по этому источнику. Оборот связан с глаголом и не отделяется запятой. В других цитатах он вводит мнение или сведения рассказчиков."]},{"author":"Б. Иомдин","question":"Слова какой части речи в русском языке реже всего стоят в конце предложения?","choices":["существительные","прилагательные","наречия","глаголы","союзы."],"key":"Д","review":["Слово в конце предложения","Вспомни, какая часть речи обычно стоит между словами или частями предложения и соединяет их.","Союз обычно вводит или присоединяет следующий элемент. Поэтому существительное, прилагательное, наречие и глагол оказываются в конце предложения чаще союза."]},{"author":"П. Аркадьев","question":"В каком глаголе нельзя вычеркнуть -<em>ва</em>- так, чтобы в результате тоже получился глагол?","choices":["<em>раздеваться</em>","<em>переодеваться</em>","<em>одеваться</em>","<em>надеваться</em>","<em>издеваться</em>."],"key":"Д","review":["Глагол без «-ва-»","Вычеркни две буквы и прочитай получившиеся формы вслух.","Получаются «раздеться», «переодеться», «одеться» и «надеться». После удаления из «издеваться» выходит «издеться», такого глагола нет."]},{"author":"А. Кухто и А. Пиперски","question":"Какое из этих слов чаще употребляется с приставкой <em>не</em>-, чем без неё?","choices":["<em>бессмысленно</em>","<em>безынтересно</em>","<em>скучно</em>","<em>уныло</em>","<em>грустно</em>."],"key":"Б","review":["Слово с приставкой «не-»","Сравни слова с приставкой и без неё. Иногда два отрицательных элемента вместе описывают умеренно положительное впечатление.","«Небезынтересно» значит «представляет некоторый интерес» и употребляется чаще «безынтересно». Для остальных слов чаще встречается вариант без «не-»."]},{"author":"П. Аркадьев","question":"Даны несколько слов и словосочетаний на итальянском языке и их перевод на русский: <em>tutto</em> ‘весь’, <em>belli ragazzi</em> ‘красивые юноши’, <em>belle ragazze</em> ‘красивые девушки’, <em>famosi poeti</em> ‘знаменитые поэты’, <em>famose italiane</em> ‘знаменитые итальянки’. Название оперы Вольфганга Амадея Моцарта “Così fan tutte” буквально переводится на русский язык «Так поступают все», однако для более точной передачи смысла обычно добавляют ещё одно слово. Какое?","choices":["люди","мужчины","музыканты","итальянцы","женщины."],"key":"Д","review":["Название оперы Моцарта","Сопоставь окончания в итальянских названиях юношей и девушек. Прилагательные с девушками и итальянками оканчиваются на «-e».","В названии «Così fan tutte» слово «tutte» тоже имеет женскую форму множественного числа. Полнее по-русски получается «Так поступают все женщины»."]},{"author":"Е. Бикмаев","question":"Какая пара слов попала в подборку лингвиста ошибочно?","choices":["<em>волочить — влачить</em>","<em>сторона — страна</em>","<em>короткий — краткий</em>","<em>огородить — оградить</em>","<em>подорожать — подражать</em>."],"key":"Д","review":["Чередование сочетаний","Сравни, какой фрагмент корня заменяется в каждой паре. «Оло» и «ла», «оро» и «ра» образуют исторические соответствия.","«Волочить — влачить», «сторона — страна», «короткий — краткий», «огородить — оградить» связаны по происхождению. В «подорожать — подражать» сходство случайное: первое слово от «дорогой», второе связано с «подражанием»."]},{"author":"Е. Бикмаев","question":"Говорят, что <em>леса — это ______ планеты</em>. Заполните пропуск.","choices":["<em>далёкие</em>","<em>тяжёлые</em>","<em>необитаемые</em>","<em>лёгкие</em>","<em>молодые</em>."],"key":"Г","review":["Сравнение о лесах","Вспомни, с каким органом человека связывают дыхание и получение кислорода.","Леса часто называют «лёгкими планеты». Сравнение подчёркивает их роль в обмене кислородом и углекислым газом."]},{"author":"П. Аркадьев","question":"Как правильно вставить пропущенные буквы во фразе <em>Ч...столюбивые труб...чисты выч...стили труб...чей</em>?","choices":["<em>е-а-е-а</em>","<em>е-о-и-а</em>","<em>и-о-и-о</em>","<em>а-о-а-а</em>","<em>е-а-и-о</em>."],"key":"Б","review":["Четыре пропущенные буквы","Разбери слова по смыслу: любят честь, чистят трубы, очищают от грязи и играют на трубе.","Пишем «честолюбивые трубочисты вычистили трубачей». Буквы по порядку — «е, о, и, а»."]},{"author":"А. Сомин","question":"Слова <em>номер</em> и <em>ноль</em>, а также производные от них обладают одним необычным свойством. Какое ещё слово им обладает?","choices":["<em>гольф</em>","<em>постель</em>","<em>стол</em>","<em>тоннель</em>","<em>ухо</em>."],"key":"Г","review":["Два варианта одного слова","Вспомни близкие по форме варианты слова «ноль». В другом слове тоже можно поменять «о» на «у».","Сравни «ноль — нуль», «номер — нумер» и «тоннель — туннель». В этих парах меняется гласная, а основное значение сохраняется."]},{"author":"И. Шаронов","question":"<em>Всё это сущая ерунда, это ______________ яйца не стоит</em>.","choices":["<em>выведенного</em>","<em>выброшенного</em>","<em>выеденного</em>","<em>разбитого</em>","<em>протухшего</em>."],"key":"В","review":["Устойчивое выражение с яйцом","Здесь ищут выражение о чём-то ничтожном, что не стоит даже пустой яичной скорлупы.","«Выеденного яйца не стоит» говорят о деле, которое не заслуживает внимания или усилий."]},{"author":"А. Кухто","question":"Дан фрагмент из дневника А. Н. Вульфа, друга А. С. Пушкина (орфография оригинала сохранена):\n<em>…тутъ же я сшилъ себѣ сертукъ, которой почти и истощилъ мою казну.</em>\nВ каком падеже здесь стоит слово <em>которой</em>?","choices":["в именительном","в родительном","в дательном","в винительном","в творительном."],"key":"А","review":["Падеж в старой цитате","Найди подлежащее глагола «истощилъ»: что именно почти истощило казну?","«Которой» относится к сюртуку и само является подлежащим придаточного. Это старая форма мужского рода именительного падежа, современное «который»."]},{"author":"С. Сай","question":"Даны существительные: <em>лето</em>, <em>небо</em>, <em>слово</em>, <em>тело</em>, <em>чудо</em>. Исторически все они, кроме одного, обладали одним редким свойством. Какое слово в этом ряду лишнее?","choices":["<em>лето</em>","<em>небо</em>","<em>слово</em>","<em>тело</em>","<em>чудо.</em>"],"key":"А","review":["Старые основы существительных","Вспомни множественное число «небеса» и «чудеса». Такая часть основы встречалась и у некоторых других слов.","У «неба», «слова», «тела» и «чуда» были формы с расширением основы на «-ес-», ср. «словеса» и «телеса». Лишнее слово — «лето»."]},{"author":"А. Панина","question":"<em>Люди издавна ______ свои чувства в художественную форму.</em> Каким словом можно заполнить пропуск?","choices":["<em>обретали</em>","<em>обрекали</em>","<em>облекали</em>","<em>обличали</em>","<em>облагали</em>."],"key":"В","review":["Глагол для выражения чувств","Глагол должен обозначать придание чувствам формы. Вспомни также выражение «облечь мысль в слова».","Именно «облекали свои чувства в художественную форму» означает, что люди давали чувствам художественное выражение."]},{"author":"П. Аркадьев","question":"<em>Найдём два процента от …</em>. Как правильно закончить эту фразу?","choices":["<em>полутора миллиона</em>","<em>полутора миллионов</em>","<em>полтора миллиона</em>","<em>полтора миллионов</em>","ни один из вариантов (А)–(Г) не является правильным."],"key":"Б","review":["Дробное числительное","Предлог «от» требует родительного падежа. Просклоняй и числительное, и название числа.","«Полтора» в родительном падеже становится «полутора», а «миллион» имеет форму «миллионов». Получаем «от полутора миллионов»."]},{"author":"А. Пиперски","question":"Выпишем все русские числительные от 1 до 100: <em>один</em>, <em>два</em>, <em>три</em>, <em>четыре</em>, …, <em>девяносто девять</em>, <em>сто</em>. Какие буквы встретятся в этом списке ровно по 10 раз?","choices":["<em>н</em> и <em>п</em>","<em>л</em> и <em>н</em>","<em>п</em>, <em>ч</em>, <em>ш</em> и <em>ы</em>","<em>и</em> и <em>н</em>","<em>к</em>, <em>ч</em> и <em>ы</em>."],"key":"Д","review":["Буквы в числительных","Сгруппируй числа по десяткам и последней цифре. Буква может появляться во всей группе с одной и той же частью слова.","«К» есть в «сорок» и девяти числах от 41 до 49. «Ч» и «ы» встречаются в «четыре», «четырнадцать» и восьми составных числительных от «двадцать четыре» до «девяносто четыре»."]},{"author":"Л. Фёдорова","question":"С чьей песней сравнивают последнее в жизни автора произведение?","choices":["жаворонка","соловья","кукушки","лебедя","петуха."],"key":"Г","review":["Последнее произведение","Ищи устойчивое название произведения, созданного автором незадолго до смерти или ухода с творческой сцены.","Это «лебединая песня». Выражение связано с преданием о том, что лебедь поёт перед смертью."]},{"author":"Е. Бикмаев","question":"Из какого глагола после вычёркивания <em>ь</em> получится личная форма того же самого глагола?","choices":["<em>извиняться</em>","<em>накаляться</em>","<em>покоряться</em>","<em>бояться</em>","<em>каяться</em>."],"key":"Г","review":["Личная форма глагола","Сравни инфинитивы с ответами на вопрос «что делают?». Проверь, какие буквы стоят перед «-тся».","Из «бояться» получается «боятся». У других глаголов нужны «извиняются», «накаляются», «покоряются» и «каются», а одного удаления «ь» недостаточно."]},{"author":"А. Пиперски","question":"В каком предложении подчёркнутая часть устроена иначе, чем в остальных?","choices":["<em>Квартиры приобретаются и переводятся после этого в нежилой фонд. Всё просто и законно, но <u>не очень быстро и дешево</u>.</em>","<em>Боли в области копчика лечатся <u>не очень быстро и хорошо</u>.</em>","<em>Впрочем, если писать текст <u>не очень быстро и аккуратно</u>, устройство будет работать намного корректнее.</em>","<em>Для снижения давления можно применить средства, действующие <u>не очень быстро и резко</u>.</em>","<em>Зачем конусы, спросите Вы? Так ведь будем выделывать фигуры и писать небольшие кульбиты, пусть <u>не очень быстро и ловко</u> для первого раза, но впечатлений хватит вполне!</em>"],"key":"В","review":["К каким словам относится «не»","Прочитай каждую фразу как описание двух признаков и проверь, с каким из них сочетается отрицание.","Текст нужно писать не очень быстро, но аккуратно. Здесь «не очень» характеризует только скорость. В остальных фразах отрицание относится к обоим признакам: например, лечение не очень быстро и не очень хорошо."]},{"author":"А. Пиперски","question":"<em>До сих пор мне было невдомёк —\nДля чего мне звёздный каталог?\nВ каталоге десять миллионов\nНомеров небесных телефонов…</em>\nТак начинается стихотворение Арсения Тарковского «Звёздный каталог». А какой номер телефона в нём упоминается?","choices":["А-89-74-75","А-13-40-25","А-51-18-03","А-33-22-70","А-01-34-32."],"key":"Б","review":["Номер в стихотворении","После приведённых строк поэт называет звезду собеседницей, которой можно позвонить. Найди место, где он набирает номер.","В «Звёздном каталоге» после слов о повороте телефонного диска указан номер «А-13-40-25». Именно его набирает герой."]},{"author":"Е. Бикмаев","question":"Какой звук русского языка не встречается перед глухими согласными звуками, но встречается после них?","choices":["[ж]","[б]","[в]","[г]","[д]."],"key":"В","review":["Звук рядом с глухим","Проверь сочетание «св» в слове «свой». Обрати внимание на разницу между местом до и после глухого согласного.","В «свой» глухой [с] сохраняется перед [в]. Сам [в] перед глухим оглушается до [ф], например в слове «лавка»."]},{"author":"И. Рубанов","question":"В 1755 году Джакомо Казанова бежал из венецианской тюрьмы, расположенной на верхнем этаже Дворца дожей. Глава его мемуаров, посвящённая этой тюрьме, в некоторых русских переводах называется «Под пломбами». Листами какого металла была покрыта крыша Дворца дожей?","choices":["железа","меди","золота","цинка","свинца."],"key":"Д","review":["Крыша Дворца дожей","Сопоставь «пломбы» с обозначениями металлов, особенно с латинским «plumbum», знакомым по символу Pb.","«Пьомби» — название венецианской тюрьмы под свинцовой крышей дворца. Латинское «plumbum» также означает свинец."]},{"author":"П. Аркадьев","question":"<em>Колосья ― так недавно <strong>сжаты</strong>,\nРядами ровными <strong>лежат</strong>;\nИ пальцы тонкие <strong>дрожат</strong>,\nК таким же, как они, <strong>прижаты</strong>.</em>\nКакие из выделенных в приведённом четверостишии Осипа Мандельштама (1909 г.) слов являются однокоренными?","choices":["<em>сжаты</em> и <em>лежат</em>","<em>лежат</em> и <em>дрожат</em>","<em>сжаты</em> и <em>прижаты</em>","все четыре","никакие два слова не однокоренные."],"key":"Д","review":["Корни в четверостишии","Найди начальные формы глаголов. Обрати внимание, что колосья срезали, а пальцы к чему-то придавили.","«Сжаты» относится к «сжать» в смысле «сжать серпом, срезать», от «жать» о жатве. «Прижаты» связано с «жать» в смысле «давить». «Лежат» и «дрожат» тоже имеют свои корни."]},{"author":"А. Кухто и А. Пиперски","question":"Дан фрагмент «Выписок из дневника, ведённого в Пекине (1848–1850)» востоковеда Василия Павловича Васильева (1818–1900): <em>…курс заметно падает перед самым новым годом, когда солдаты получают двойное месячное жалованье, чиновники третное, и притом всякий достает заветное серебро, чтоб сделать нужные покупки или расплатиться с долгами перед праздником.</em> Жалованье за сколько месяцев получают чиновники перед новым годом?","choices":["за два","за три","за четыре","за пять","за шесть."],"key":"В","review":["Третное жалованье","Сопоставь параллельные части предложения: солдатам выдают двойное месячное жалованье, а чиновникам — третное.","В этой цитате «третное» противопоставлено «двойному» и значит «тройное». Чиновники получают сумму за три месяца."]},{"author":"Е. Муравенко","question":"Какие из данных причастий представляют собой исключения из общего правила образования причастий: <em>руководимый</em>, <em>управляемый</em>, <em>возглавляемый</em>?","choices":["только <em>руководимый</em>","только <em>управляемый</em>","<em>руководимый</em> и <em>управляемый</em>","<em>управляемый</em> и <em>возглавляемый</em>","исключений нет."],"key":"В","review":["Образование причастий","Вспомни, от каких глаголов обычно образуются страдательные причастия. Проверь, можно ли поставить после каждого глагола прямое дополнение.","Говорят «руководить отделом» и «управлять отделом», с творительным падежом. «Руководимый» и «управляемый» — исключения. «Возглавлять отдел» требует винительного, поэтому «возглавляемый» образовано по правилу."]}], {"year":2017,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2017-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
